def balance_bst(root):
    nodes = []

    def walk(node):
        if node is not None:
            walk(node.left)
            nodes.append(node)
            walk(node.right)

    walk(root)

    def make(lo, hi):
        if lo > hi:
            return None
        mid = (lo + hi) // 2
        node = nodes[mid]
        node.left, node.right = make(lo, mid - 1), make(mid + 1, hi)
        return node

    return make(0, len(nodes) - 1)
